const input = $input.first()?.json || {};

function cleanOuterQuotes(value) {
  let text = String(value ?? '').trim();
  const pairs = [['"', '"'], ["'", "'"], ['“', '”'], ['‘', '’']];
  for (const [left, right] of pairs) {
    if (text.startsWith(left) && text.endsWith(right) && text.length >= left.length + right.length) {
      text = text.slice(left.length, text.length - right.length).trim();
      break;
    }
  }
  return text;
}

function cleanFolderPath(value) {
  const text = cleanOuterQuotes(value);
  if (!/^file:\/\//i.test(text)) return text;
  try {
    const url = new URL(text);
    let pathname = decodeURIComponent(url.pathname || '');
    if (/^\/[A-Za-z]:\//.test(pathname)) pathname = pathname.slice(1);
    if (url.host && url.host.toLowerCase() !== 'localhost') return '//' + url.host + pathname;
    return pathname;
  } catch {
    return text;
  }
}

const normalized = {
  folderPath: cleanFolderPath(input.folderPath),
  filePrefix: String(input.filePrefix || 'n8n_setParameter_').trim() || 'n8n_setParameter_',
  fileExtension: String(input.fileExtension || '.json').trim() || '.json',
  returnMode: 'latest',
};

return [{
  json: {
    ...normalized,
    scanInputBase64: Buffer.from(JSON.stringify(normalized), 'utf8').toString('base64'),
  },
}];

const commandOutput = $input.first()?.json || {};
const normalized = $('Normalize Input').first()?.json || {};

function internalFailure() {
  return {
    success: false,
    returnMode: 'latest',
    errorType: 'INTERNAL_EXECUTION_ERROR',
    rootFolderPath: normalized.folderPath || '',
    latestFile: null,
    data: null,
    message: '执行本地 JSON 扫描命令失败',
    warnings: [],
  };
}

let response;
try {
  const stdout = typeof commandOutput.stdout === 'string' ? commandOutput.stdout.trim() : '';
  if (!stdout) throw new Error('Missing stdout');
  response = JSON.parse(stdout);
  if (!response || typeof response !== 'object' || typeof response.success !== 'boolean') {
    throw new Error('Invalid response');
  }
} catch {
  response = internalFailure();
}

return [{ json: response }];
